<script setup lang="ts">
import { RefreshCw, Clock3, Play } from '@lucide/vue'
import { clone, state, refresh, perform, runSource, saveConfiguration } from '../../app/state'
import type { Source } from '../../app/types'
import { time } from '../../app/format'
import StackedTime from '../../components/StackedTime.vue'
async function toggle(source: Source) { if(!state.config)return;const config=clone(state.config.config);const item=config.sources.find(s=>s.id===source.id)!;item.schedule.enabled=!item.schedule.enabled;await saveConfiguration(config) }
async function cron(source: Source,event: Event) { const value=(event.target as HTMLInputElement).value;if(value===source.schedule.cron)return;if(!state.config)return;const config=clone(state.config.config);config.sources.find(s=>s.id===source.id)!.schedule.cron=value;await saveConfiguration(config) }
</script>
<template><section><div class="page-heading"><div><span class="eyebrow">AUTOMATION</span><h1>计划管理<span>.</span></h1></div><button class="button" @click="perform(refresh)"><RefreshCw :size="16"/>刷新</button></div><div class="panel"><div class="table-scroll"><table><thead><tr><th class="text-left">同步源</th><th>cron 表达式</th><th>下次运行</th><th>自动计划</th><th>操作</th></tr></thead><tbody><tr v-for="source in state.config?.config.sources" :key="source.id"><td class="text-left"><strong>{{source.name}}</strong><small>{{source.type}}</small></td><td><input class="cron-input" :value="source.schedule.cron" aria-label="cron 表达式" @change="perform(()=>cron(source,$event))"/></td><td class="schedule-timestamp"><StackedTime v-if="source.enabled&&source.schedule.enabled" :value="time(state.info?.schedules[source.id])" :datetime="state.info?.schedules[source.id]"/><span v-else class="muted">未启用</span></td><td><button class="toggle" :class="{on:source.schedule.enabled}" :aria-pressed="source.schedule.enabled" :aria-label="'自动计划 '+source.name" @click="perform(()=>toggle(source))"><span></span></button><small v-if="!source.enabled" class="error-text">同步源已禁用</small></td><td class="right"><button class="button compact" :disabled="!source.enabled" @click="perform(()=>runSource(source.id))"><Play :size="14"/>立即同步</button></td></tr><tr v-if="!state.config?.config.sources.length"><td colspan="5" class="empty-state"><Clock3 :size="32"/><h3>暂无运行计划</h3><p>先在同步源页面新增来源。</p></td></tr></tbody></table></div></div></section></template>
